import logging
import os
import threading
from datetime import datetime, timezone
from pathlib import Path
from typing import Dict, List, Optional, Set

from src.wal_codec import WalCodec, JsonlCodec, WalDecodeError, resolve_codec

logger = logging.getLogger(__name__)

STATUS_PENDING = "pending"
STATUS_IN_PROGRESS = "in_progress"
STATUS_COMPLETED = "completed"
STATUS_FAILED = "failed"

DEFAULT_HEARTBEAT_SECONDS = 600
DEFAULT_COMPACT_THRESHOLD = 10000
DEFAULT_MAX_ATTEMPTS = 3


def _generate_microbatch_id() -> str:
    now = datetime.now(timezone.utc)
    date_part = now.strftime("%Y-%m-%d")
    return f"{date_part}-{now.strftime('%H%M%S')}"


class WriteAheadLog:
    """
    Append-only JSONL write-ahead log for batch processing crash recovery.

    Lives at <folder>/.open-photo-agent/wal.jsonl
    """

    def __init__(
        self,
        folder: str,
        codec: Optional[WalCodec] = None,
        codec_name: Optional[str] = None,
        heartbeat_seconds: int = DEFAULT_HEARTBEAT_SECONDS,
        max_attempts: int = DEFAULT_MAX_ATTEMPTS,
        compact_threshold: int = DEFAULT_COMPACT_THRESHOLD,
    ):
        """Open (or create) the WAL for a given folder and load+repair on init.

        On construction the WAL is fully read into an in-memory index.
        Any ``in_progress`` entries older than ``heartbeat_seconds`` are
        automatically reset to ``pending`` (or ``failed`` if the retry
        limit is exceeded).
        """
        self._folder = Path(folder).absolute()
        self._heartbeat_seconds = heartbeat_seconds
        self._max_attempts = max_attempts
        self._compact_threshold = compact_threshold

        if codec is not None:
            self._codec = codec
        else:
            self._codec = self._resolve_codec_from_disk(codec_name)

        self._wal_dir = self._folder / ".open-photo-agent"
        self._path = self._wal_dir / f"wal{self._codec.file_extension}"
        self._lock = threading.Lock()

        self._index: Dict[str, Dict] = {}
        self._seq_counter: int = 0
        self._load_and_repair()

    def _resolve_codec_from_disk(self, codec_name: Optional[str]) -> WalCodec:
        wal_dir = self._folder / ".open-photo-agent"
        for ext, cls in {
            ".jsonl": JsonlCodec,
        }.items():
            candidate = wal_dir / f"wal{ext}"
            if candidate.exists():
                return cls()

        if codec_name:
            if codec_name == "jsonl":
                return JsonlCodec()
            raise ValueError(f"Unknown codec name: {codec_name!r}")
        return JsonlCodec()

    def _load_and_repair(self):
        self._index.clear()
        self._seq_counter = 0

        if not self._path.exists():
            return

        raw_lines = []
        try:
            with open(self._path, "rb") as f:
                raw_lines = f.read().split(b"\n")
        except OSError:
            return

        for line in raw_lines:
            if not line.strip():
                continue
            try:
                entry = self._codec.decode(line)
                img_path = entry.get("image_path", "")
                if img_path:
                    self._index[img_path] = entry
                seq = entry.get("seq", 0)
                if seq > self._seq_counter:
                    self._seq_counter = seq
            except WalDecodeError:
                logger.warning(
                    "Skipping corrupt/truncated WAL line in %s", self._path
                )
                continue

        self._repair_abandoned()

    def _repair_abandoned(self):
        now = datetime.now(timezone.utc)
        reset_count = 0

        for img_path, entry in list(self._index.items()):
            if entry.get("status") != STATUS_IN_PROGRESS:
                continue
            ts_str = entry.get("ts", "")
            try:
                ts = datetime.fromisoformat(ts_str)
            except (ValueError, TypeError):
                continue
            elapsed = (now - ts).total_seconds()
            if elapsed > self._heartbeat_seconds:
                attempt = entry.get("attempt", 1) + 1
                if attempt > self._max_attempts:
                    new_entry = {
                        "seq": self._next_seq(),
                        "image_path": img_path,
                        "status": STATUS_FAILED,
                        "microbatch_id": entry.get("microbatch_id", ""),
                        "ts": now.isoformat(),
                        "attempt": entry.get("attempt", 1),
                        "sidecar_path": entry.get("sidecar_path"),
                        "error_code": "abandoned_heartbeat",
                        "error_msg": f"Abandoned in_progress after {self._heartbeat_seconds}s, max attempts exceeded",
                    }
                else:
                    new_entry = {
                        "seq": self._next_seq(),
                        "image_path": img_path,
                        "status": STATUS_PENDING,
                        "microbatch_id": entry.get("microbatch_id", ""),
                        "ts": now.isoformat(),
                        "attempt": attempt,
                        "sidecar_path": entry.get("sidecar_path"),
                        "error_code": None,
                        "error_msg": None,
                    }
                self._index[img_path] = new_entry
                reset_count += 1
                logger.warning(
                    "Resetting abandoned in_progress entry: %s (attempt %d)",
                    img_path,
                    attempt,
                )

        if reset_count:
            self._rewrite_wal()

    def _next_seq(self) -> int:
        self._seq_counter += 1
        return self._seq_counter

    def _append_raw(self, raw: bytes):
        self._wal_dir.mkdir(parents=True, exist_ok=True)
        try:
            with open(self._path, "ab") as f:
                f.write(raw)
                f.flush()
                os.fsync(f.fileno())
        except OSError as e:
            logger.error("Failed to append to WAL %s: %s", self._path, e)
            raise

    def append(
        self,
        image_path: str,
        status: str,
        microbatch_id: str,
        attempt: int = 1,
        sidecar_path: Optional[str] = None,
        error_code: Optional[str] = None,
        error_msg: Optional[str] = None,
    ) -> int:
        """Append a lifecycle event for an image to the WAL (thread-safe).

        Args:
            image_path: Absolute path to the image file.
            status: One of ``pending``, ``in_progress``, ``completed``, ``failed``.
            microbatch_id: Identifier for the current micro-batch run.
            attempt: Retry attempt number (1-based).
            sidecar_path: Optional path to the corresponding sidecar JSON.
            error_code: Optional error code string on failure.
            error_msg: Optional error message string on failure.

        Returns:
            The monotonically-increasing sequence number of the entry.
        """
        with self._lock:
            entry = {
                "seq": self._next_seq(),
                "image_path": image_path,
                "status": status,
                "microbatch_id": microbatch_id,
                "ts": datetime.now(timezone.utc).isoformat(),
                "attempt": attempt,
                "sidecar_path": sidecar_path,
                "error_code": error_code,
                "error_msg": error_msg,
            }
            self._index[image_path] = entry
            raw = self._codec.encode(entry)
            self._append_raw(raw)
            return entry["seq"]

    def get_status(self, image_path: str) -> Optional[str]:
        """Return the current lifecycle status for a single image, or None."""
        with self._lock:
            entry = self._index.get(image_path)
            if entry is None:
                return None
            return entry.get("status")

    def get_pending(self) -> List[str]:
        """Return paths of all images in pending or in_progress state."""
        with self._lock:
            return [
                path
                for path, entry in self._index.items()
                if entry.get("status") in (STATUS_PENDING, STATUS_IN_PROGRESS)
            ]

    def get_completed_set(self) -> Set[str]:
        """Return a set of image paths that have been successfully completed."""
        with self._lock:
            return {
                path
                for path, entry in self._index.items()
                if entry.get("status") == STATUS_COMPLETED
            }

    def get_failed(self) -> List[dict]:
        """Return a list of failed entries with path, error_code, and error_msg."""
        with self._lock:
            return [
                {
                    "image_path": entry.get("image_path"),
                    "error_code": entry.get("error_code"),
                    "error_msg": entry.get("error_msg"),
                }
                for entry in self._index.values()
                if entry.get("status") == STATUS_FAILED
            ]

    def get_active_microbatch_id(self) -> Optional[str]:
        """Return the microbatch_id of any in-flight (pending/in_progress) entry."""
        with self._lock:
            for entry in self._index.values():
                if entry.get("status") in (STATUS_PENDING, STATUS_IN_PROGRESS):
                    return entry.get("microbatch_id")
            return None

    def get_stats(self) -> Dict:
        """Return aggregate counts: total, completed, failed, pending."""
        with self._lock:
            total = len(self._index)
            completed = sum(
                1 for e in self._index.values() if e.get("status") == STATUS_COMPLETED
            )
            failed = sum(
                1 for e in self._index.values() if e.get("status") == STATUS_FAILED
            )
            pending = sum(
                1
                for e in self._index.values()
                if e.get("status") in (STATUS_PENDING, STATUS_IN_PROGRESS)
            )
            return {
                "total": total,
                "completed": completed,
                "failed": failed,
                "pending": pending,
            }

    def prune(self, keep_completed: bool = True) -> int:
        """Remove failed (and optionally completed) entries and rewrite the WAL.

        Returns the number of entries removed.
        """
        with self._lock:
            removed = 0
            to_keep: Dict[str, Dict] = {}
            for path, entry in self._index.items():
                status = entry.get("status")
                if status == STATUS_COMPLETED and keep_completed:
                    to_keep[path] = entry
                elif status == STATUS_COMPLETED and not keep_completed:
                    removed += 1
                elif status == STATUS_FAILED:
                    removed += 1
                else:
                    to_keep[path] = entry
            self._index = to_keep
            self._rewrite_wal()
            return removed

    def compact(self) -> int:
        """Rewrite the WAL keeping only the latest entry per image.

        Returns the number of entries before compaction.
        """
        with self._lock:
            old_count = len(self._index)
            self._rewrite_wal()
            return old_count

    def auto_compact_if_needed(self) -> bool:
        """Compact the WAL if the entry count exceeds the configured threshold.

        Returns True if compaction was performed.
        """
        with self._lock:
            line_count = len(self._index)
            if line_count > self._compact_threshold:
                logger.info(
                    "WAL has %d entries (>%d), auto-compacting...",
                    line_count,
                    self._compact_threshold,
                )
                self._rewrite_wal()
                return True
            return False

    def _rewrite_wal(self):
        self._wal_dir.mkdir(parents=True, exist_ok=True)
        tmp_path = self._path.with_suffix(".tmp")
        try:
            with open(tmp_path, "wb") as f:
                for entry in sorted(
                    self._index.values(), key=lambda e: e.get("seq", 0)
                ):
                    f.write(self._codec.encode(entry))
                    f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, self._path)
        except OSError as e:
            logger.error("Failed to rewrite WAL %s: %s", self._path, e)
            if tmp_path.exists():
                try:
                    tmp_path.unlink()
                except OSError:
                    pass
            raise


def generate_microbatch_id() -> str:
    """Create a unique micro-batch ID in ``YYYY-MM-DD-HHMMSS`` format."""
    return _generate_microbatch_id()

from datetime import datetime, timezone
from pathlib import Path
from typing import List, Optional, Set
import logging

from src.sidecar.database import FeaturesDatabase
from src.sidecar.writer import SidecarWriter

logger = logging.getLogger(__name__)

class PhotoList:
    """Handles discovery and listing of photos in specified folders."""

    def __init__(self, recursive: bool = True, extensions: Set[str] = None):
        """Initialise the photo discovery helper.

        Args:
            recursive: If True, scan sub-directories recursively.
            extensions: Set of lowercase file extensions to include.
                Defaults to common image formats.
        """
        self.recursive = recursive
        self.extensions = extensions or {".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp", ".tiff", ".tif", ".heic", ".heif"}

    def list_photos(
        self,
        paths: List[str],
        limit: Optional[int] = None,
        exclude_processed_from: Optional[str] = None,
    ) -> List[str]:
        """
        Expand directories into image file paths.

        Args:
            paths: List of paths (files or directories).
            limit: If set, return at most this many image paths.
            exclude_processed_from: If set to a directory path, use WAL,
                DB, or legacy sidecar fallback to exclude completed images.

        Returns:
            List of absolute image file paths.
        """
        images = []
        logger.info(f"Listing photos for paths: {paths}")
        for p in paths:
            path = Path(p).absolute()
            logger.info(f"Checking path: {path} (Exists: {path.exists()}, IsDir: {path.is_dir()})")
            if path.is_dir():
                # Ensure features database exists for this folder
                try:
                    db_path = FeaturesDatabase.default_db_path(str(path))
                    db = FeaturesDatabase(db_path)
                    db.init_db()
                    db.close()
                except Exception:
                    logger.warning("Failed to init features DB for %s", path, exc_info=True)

                if self.recursive:
                    candidates = list(path.rglob("*"))
                    logger.info(f"Found {len(candidates)} total candidates in {path} (recursive)")
                else:
                    candidates = list(path.iterdir())
                    logger.info(f"Found {len(candidates)} total candidates in {path} (non-recursive)")
                for child in candidates:
                    if child.is_file() and child.suffix.lower() in self.extensions:
                        images.append(str(child))
            elif path.is_file():
                if path.suffix.lower() in self.extensions:
                    images.append(str(path))
                else:
                    logger.warning(f"File is not a supported image: {p}")
            else:
                logger.warning(f"Path not found: {p}")

        logger.info(f"Total images discovered: {len(images)}")

        if exclude_processed_from:
            processed = self._load_processed_set(exclude_processed_from)
            if processed:
                images = [img for img in images if img not in processed]
                logger.info(f"After excluding {len(processed)} processed: {len(images)} remaining")

        if limit is not None:
            images = images[:limit]
            logger.info(f"After limiting to {limit}: {len(images)} remaining")

        return images

    @staticmethod
    def _load_processed_set(image_dir: str) -> set:
        """Build a set of already-processed image paths from WAL, DB, or legacy sidecars.

        Prefers WAL data. Falls back to the ``features.db`` rows. Finally
        scans legacy sidecar JSONs. If sidecars are found and no WAL
        exists, auto-migrates the sidecar entries into the WAL.
        """
        from src.wal import WriteAheadLog

        wal = WriteAheadLog(image_dir)
        if wal._path.exists():
            completed = wal.get_completed_set()
            if completed:
                return completed

        # Check DB next (new source of truth)
        db_path = FeaturesDatabase.default_db_path(image_dir)
        if db_path.exists():
            try:
                db = FeaturesDatabase(db_path)
                db.init_db()
                extractions = db.list_extractions()
                db.close()
                processed = {
                    ex["image_path"] for ex in extractions
                    if ex.get("image_path")
                }
                if processed:
                    return processed
            except Exception:
                logger.warning("Failed to read features DB for %s", image_dir, exc_info=True)

        # Legacy JSON sidecar fallback
        sidecar_dir = Path(image_dir) / ".open-photo-agent" / "data"
        if not sidecar_dir.is_dir():
            return set()

        processed = set()
        parent_dir = sidecar_dir.parent.parent
        for f in sidecar_dir.iterdir():
            if f.suffix == ".json":
                image_name = f.stem
                image_path = str(parent_dir / image_name)
                data = SidecarWriter.load(image_path)
                if data:
                    img_path = data.get("image_path")
                    if img_path:
                        processed.add(img_path)

        if processed and not wal._path.exists():
            logger.info("Auto-migrating %d sidecars to WAL in %s", len(processed), image_dir)
            microbatch_id = f"migrate-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}"
            for img_path in processed:
                sidecar_name = Path(img_path).name + ".json"
                full_sidecar = str(sidecar_dir / sidecar_name)
                wal.append(img_path, "completed", microbatch_id, sidecar_path=full_sidecar)

        return processed

import logging
import mimetypes
from importlib import import_module
from pathlib import Path
from typing import Optional, Union

from plugins.formats.registry import get_reader

logger = logging.getLogger(__name__)


_readers_imported = False


def _ensure_plugins_loaded():
    """Auto-discover and import format plugin sub-packages under plugins.formats."""
    global _readers_imported
    if _readers_imported:
        return
    _readers_imported = True

    import plugins.formats
    import pkgutil
    for _, name, is_pkg in pkgutil.iter_modules(plugins.formats.__path__, plugins.formats.__name__ + "."):
        if is_pkg:
            try:
                import_module(name)
            except Exception:
                logger.warning("Failed to load format plugin %s", name, exc_info=True)


def _detect_extension_by_magic(path: Path) -> Optional[str]:
    """Try to determine the image file extension from magic bytes in the header.

    Returns a lowercase extension (e.g. ``'.jpg'``) or None if unrecognised.
    """
    try:
        with open(path, "rb") as f:
            header = f.read(12)
    except OSError:
        return None

    if header[:2] == b"\xff\xd8\xff":
        return ".jpg"
    if header[:8] == b"\x89PNG\r\n\x1a\n":
        return ".png"
    if header[:6] in (b"GIF87a", b"GIF89a"):
        return ".gif"
    if header[:2] == b"BM":
        return ".bmp"
    if header[:4] in (b"II*\x00", b"MM\x00*"):
        return ".tif"
    if header[:4] == b"RIFF" and header[8:12] == b"WEBP":
        return ".webp"
    if header[4:8] == b"ftyp":
        # ISO base media file format (HEIC/HEIF)
        if b"heic" in header[8:].lower():
            return ".heic"
        if b"heif" in header[8:].lower():
            return ".heif"

    return None


def read_image_bytes(image_path: Union[str, Path]) -> bytes:
    """Read an image file into raw bytes, dispatching through the plugin registry.

    Falls back to raw binary read if the format is not recognised.
    Raises FileNotFoundError if the path does not exist.
    """
    _ensure_plugins_loaded()

    path = Path(image_path)
    if not path.exists():
        raise FileNotFoundError(f"Image not found: {image_path}")

    suffix = path.suffix.lower()
    reader = get_reader(suffix)
    if reader is not None:
        return reader(path)

    # Extension-based lookup failed, try MIME-type detection
    mime_type, _ = mimetypes.guess_type(str(path))
    if mime_type and mime_type.startswith("image/"):
        ext = mimetypes.guess_extension(mime_type)
        if ext:
            reader = get_reader(ext.lower())
            if reader is not None:
                return reader(path)

    # Content-based detection via magic bytes
    magic_ext = _detect_extension_by_magic(path)
    if magic_ext:
        reader = get_reader(magic_ext)
        if reader is not None:
            return reader(path)

    with open(path, "rb") as f:
        return f.read()
